def read(path): return (root/path).read_text()
def write(path,text):
    p=root/path
    p.parent.mkdir(parents=True,exist_ok=True)
    p.write_text(text)
def replace(path,old,new,count=1):
    text=read(path)
    if old not in text:
        raise SystemExit(f'missing replacement in {path}: {old[:100]!r}')
    write(path,text.replace(old,new,count))
def loadj(path): return json.loads(read(path))
def savej(path,value): write(path,json.dumps(value,ensure_ascii=False,indent=2)+'\n')
def decode(value): return base64.b64decode(value).decode()

